using System.Text.Json;using Microsoft.Extensions.Configuration;using Qms.Contracts.InternalAudits;using Qms.Infrastructure.InternalAudits;
namespace Qms.IntegrationTests;
public sealed class InternalAuditFinalReportTests
{
 [Fact]public async Task Closed_internal_audit_produces_immutable_pdf_with_signatures(){if(!File.Exists("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf"))return;var root=Path.Combine(Path.GetTempPath(),"qms-m07-pdf-tests",Guid.NewGuid().ToString("N"));var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"FileStorage:RootPath",root}}).Build();var now=new DateTimeOffset(2026,8,26,10,0,0,TimeSpan.Zero);var id=Guid.NewGuid();var record=new InternalAuditRecordResponse(id,Guid.NewGuid(),"İD-2026-000999",2026,"Üretim veri bütünlüğü denetimi","Routine","Batch ve elektronik kayıtlar","ALCOA+ uygunluğunu doğrulamak","ISO 9001 7.5",Guid.NewGuid(),"Üretim",Guid.NewGuid(),"Selin Arslan","Kalite Güvence",now.AddDays(-5),now.AddDays(-4),false,null,"IA-2026.1",now.AddDays(-5),true,"Tüm bulgular doğrulanarak kapatıldı.","Closed",now.AddDays(-6),now,now,15);var checklist=new[]{new AuditChecklistItemResponse(Guid.NewGuid(),1,"Kayıtlar izlenebilir mi?","ISO 9001 7.5","Conform","BPR-01","Uygun",now.AddDays(-4))};var findings=new[]{new AuditFindingResponse(Guid.NewGuid(),"BLG-2026-000999","Pasif erişim","Bir erişim açık kalmıştır.","SOP-IA-01",2,2,4,"Observation",false,null,null,Guid.NewGuid(),"Hakan Özkan",now.AddDays(-1),"Kabul edildi","Erişim kapatıldı","Kanıt doğrulandı","Closed",now.AddDays(-4),now)};var audit=new[]{new InternalAuditEventResponse(Guid.NewGuid(),15,"InternalAuditStatusChanged","Dr. Aylin Kurt",now,"Nihai kapanış",JsonDocument.Parse("{}").RootElement.Clone())};var signs=new[]{new InternalAuditSignatureResponse(Guid.NewGuid(),4,Guid.NewGuid(),"Dr. Aylin Kurt","İç denetim planı ve soru listesi onayı",now.AddDays(-5),new string('a',64),null),new InternalAuditSignatureResponse(Guid.NewGuid(),15,Guid.NewGuid(),"Dr. Aylin Kurt","İç denetim nihai kapanış onayı",now,new string('b',64),"Nihai kapanış")};var details=new InternalAuditDetailsResponse(record,checklist,findings,audit,signs,[],[]);var service=new InternalAuditFinalReportService(config);var first=await service.EnsureGeneratedAsync(details,CancellationToken.None);var second=await service.EnsureGeneratedAsync(details,CancellationToken.None);Assert.True(first.Content.Length>5000);Assert.Equal(first.Sha256,second.Sha256);Assert.Equal(first.Content,second.Content);}
}
